pub fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Assumptions from the prompt:
    // - arr is non-empty
    // - rectangular: all rows have the same length
    let rows = arr.len();
    let cols = arr[0].len();

    // Create output with shape (cols x rows) and fill it.
    let mut out = vec![vec![0i8; rows]; cols];
    for i in 0..rows {
        for j in 0..cols {
            out[j][i] = arr[i][j];
        }
    }
    out
}

